# DK SSB.  Sønderborg - Skovby
#
let ss = path("d3.dk.ssb");

with detail = 4, railway = :first :g1000 :pax :removed {
    with link = "line.dk.SSB" {
        track(ss[:vol.yv, :vol - 0.49sw]);
    }

    with link = "point.dk.Vollerup-ABA", railway = :station {
        track(ss[:vol - 0.5sw, :vol.yn]);
        marker(:right :de.bf :casing, ss[:vol] >> 0.5mt);
        station(:top, ss[:vol] << 0.5mt + (-0.5dt, -0.8dt),
            span(:former, "Wollerup"),
            span(:bold, "Vollerup"),
            hbox(:center:top,
                vbox(:right:top, "VNB: ", "SSB: "),
                vbox(:left:top, "4,5", "4,5")
            )
        );
    }

    with link = "line.dk.SSB" {
        track(ss[:vol.yn - 0.1dl, :vol.yn + 0.76km]);
        line_label(:left:s, ss[:vol.yn + 0.75km] << 0.5lt, "SSB");
        track(ss[:vol.yn + 0.74km, :vol.yn + 1.01km]);
        track(ss[:vol.yn + 0.99km, :vol.yo - 0.4km]);
        track(:station, ss[:vol.yo - 0.41km, :vol.yo]);
    }

    with link = "line.dk.SSB" {
        track(:station, ss[:maj.yo, :bjo - 0.49sw]);
    }

    with link = "point.dk.Bjørnemosegaard", railway = :station {
        track(ss[:bjo - 0.5sw, :bjo + 0.5sw]);
        marker(:right :de.hp :casing, ss[:bjo] >> 0.5lt);
        station(:bottom, ss[:bjo] >> 0.5lt >> 1sh >> 0.6dt,
            span(:former, "Björnemoosegaard"),
            "Bjørnemosegaard",
            "SSB: 10,4"
        );
    }

    with link = "line.dk.SSB" {
        track(ss[:bjo + 0.49sw, :tan - 0.49sw]);
    }

    with link = "point.dk.Tandslet", railway = :station {
        track(ss[:tan - 0.5sw, :tan + 0.5sw]);
        marker(:right :de.bf :casing, ss[:tan] >> 0.5lt);
        station(:top, ss[:tan] << 0.5lt + (0.5dt, -1dt),
            "Tandslet", "SSB: 11,9"
        );
    }

    with link = "line.dk.SSB" {
        track(ss[:tan + 0.49sw, :nta.yt - 0.99seg]);
        track(:station, ss[:nta.yt - 1seg, :nta.yt]);
    }

    with link = "line.dk.SSB" {
        track(:station, ss[:lmo.ys, :lmo.ys + 0.5seg]);
        track(ss[:lmo.ys + 0.49seg, :lmo.ys + 1.11km]);
        line_label(:left:w, ss[:lmo.ys + 1.1km] >> 0.5lt, "SSB");
        track(ss[:lmo.ys + 1.09km, :lys - 0.49sw]);
    }

    with link = "point.dk.Lysabild", railway = :station {
        track(ss[:lys - 0.5sw, :lys + 0.5sw]);
        marker(:left :de.bf, ss[:lys] << 0.5lt);
        station(:bottom, ss[:lys] << 0.5lt << 1sh + (2dt, 1dt),
            span(:former, "Lysabbel"),
            "Lysabild",
            "SSB: 16,6"
        );
    }

    with link = "line.dk.SSB" {
        track(ss[:lys + 0.49sw, :fje - 0.49sw]);
    }

    with link = "point.dk.Fjelby", railway = :station {
        track(ss[:fje - 0.5sw, :fje + 0.5sw]);
        marker(:right :de.bf, ss[:fje] >> 0.5lt);
        station(:left, ss[:fje] >> 0.5lt >> 1sh + (-1.4dt, 1.3dt),
            "Fjelby", "SSB: 17,0"
        );
    }

    with link = "line.dk.SSB" {
        track(ss[:fje + 0.49sw, :sko - 0.49sw]);
    }

    with link = "point.dk.Skovby-Als", railway = :station {
        track(ss[:sko - 0.5sw, :sko + 0.5sw]);
        marker(:left :de.bf, ss[:sko] << 0.5lt);
        station(:right, ss[:sko] << 0.5lt << 1sh + (1.5dt, 1.2dt),
            span(:former, "Schauby"),
            span(:bold, "Skovby"),
            "SSB: 19,0"
        );
    }
}

